    description:
      'The Saigon Notre-Dame Cathedral Basilica is one of the landmark buildings of Ho Chi Minh City. Located in the heart of the city, it was built in the late 19th century. The architecture of the cathedral is a blend of Romanesque and Gothic styles, exuding classical and elegant features. Its facade boasts two bell towers towering approximately 57 meters high, housing a set of six bells (Do, Re, Mi, Fa, Sol, La). In the garden square in front of the cathedral stands a 4.6-meter-tall, 8-ton statue of Virgin Mary, regarded as the symbol of the Notre-Dame Cathedral. On weekdays, the cathedral holds two masses, one at 5:30 am and another in the evening at 5:30 pm. On Sundays, there are seven masses scheduled at 5:30 am, 6:45 am, 8 am, 9:30 am (English mass), 4 pm, 5:30 pm, and 6:30 pm."',
