    cor: '10.7768252,106.6964241',
    address: '86 Le Thanh Ton Street, Ben Nghe Ward, District 1',
    description:
      "The headquarters of the People's Committee of Ho Chi Minh City is the most unique tourist attraction in the city. It not only reflects the rich history and evidences the development of Vietnam but also embodies values in the fields of painting, architecture, and sculpture. Construction began in 1898 and was officially completed in 1908. The most prominent feature of the building is its Renaissance architecture, Art Nouveau wrought-iron gates (popular at the end of the 19th century), Baroque and Rococo-style bas-reliefs famous from the 16th to the 18th century. Furthermore, the interior design of this building embodies the utmost luxury and elegance of painting and sculpture in the Louis XV era.",
