    address: '2 Nguyen Binh Khiem Street, Ben Nghe Ward, District 1',
    description:
      'The History Museum is a place dedicated to collecting and preserving the unique cultural heritage of the Vietnamese people. Housed in a century-old building constructed by the French nearly a century ago in 1929, it embodies the characteristic "Indochina modern" architectural style. Spanning an area of 6,057m², the Ho Chi Minh City History Museum comprises two buildings. Visitors to this museum can take just 365 steps around it to traverse thousands of years of Vietnamese history and culture, learning about the distinctive culture of Vietnam through its permanent and special exhibition rooms. The museum\'s collection, carefully curated from over 43,000 documents and artifacts, includes 12 national treasures displayed in various exhibition rooms, offering invaluable insights into the historical and cultural heritage of Vietnam. The museum is open to visitors on all days of the week from 8:00 to 11:30 and 13:30 to 17:00, except Mondays.',
