      '{\n  "rating": 4.8,\n  "totalReview": 8500,\n  "visitors": 400000,\n  "images": [\n  ],\n  "about": "Recognized as a UNESCO Global Geopark in 2010, Dong Van Karst Plateau spans four districts: Quan Ba, Yen Minh, Dong Van, and Meo Vac. The geopark preserves geological heritage spanning from the Cambrian to Triassic periods (500-250 million years ago). It\'s home to 17 ethnic minority groups, with traditional villages scattered throughout the dramatic limestone landscape. The area includes important historical sites such as the Vuong Palace and numerous ancient fossils.",\n  "highLights": [\n    {\n      "icon": "🗻",\n      "title": "UNESCO Global Geopark",\n      "subTitle": "First geopark in Vietnam showcasing 500 million years of geological history"\n    },\n    {\n      "icon": "🏘️",\n      "title": "Ethnic Cultural Heritage",\n      "subTitle": "17 ethnic minority groups preserving traditional lifestyles in mountain villages"\n    },\n    {\n      "icon": "🌄",\n      "title": "Dramatic Karst Landscape",\n      "subTitle": "Spectacular limestone peaks, deep valleys, and terraced agricultural fields"\n    }\n  ],\n  "activities": [\n    {\n      "icon": "🛵",\n      "title": "Motorbike Loop Tours",\n      "description": "Multi-day motorbike adventures through remote mountain passes and villages"\n    },\n    {\n      "icon": "🏠",\n      "title": "Homestay Experiences",\n      "description": "Stay with local families to experience authentic ethnic minority culture"\n    },\n    {\n      "icon": "🥾",\n      "title": "Trekking & Hiking",\n      "description": "Trek through limestone mountains and visit isolated ethnic villages"\n    }\n  ],\n  "detail": {\n    "title": "Dong Van Karst Plateau – Living Geological Museum",\n    "content": "This remarkable geopark offers visitors a unique combination of spectacular natural beauty and authentic cultural immersion. The journey through winding mountain roads reveals not only millions of years of Earth\'s geological history carved in stone but also the resilient spirit of ethnic communities who have adapted their lives to this challenging yet magnificent landscape over countless generations."\n  },\n  "reviews": [\n    {\n      "name": "Mountain_Explorer_Jake",\n      "rating": 5.0,\n      "date": "2025-07-08",\n      "comment": "Incredible motorbike journey! The landscapes are otherworldly and the ethnic villages offer authentic cultural experiences."\n    },\n    {\n      "name": "GeoTraveler_Lisa",\n      "rating": 4.6,\n      "date": "2025-06-15",\n      "comment": "Fascinating geological formations and rich cultural heritage. The homestay experience was unforgettable."\n    }\n  ],\n  "nearbyAttractions": [\n    {\n      "name": "Ma Pi Leng Pass",\n      "distance": 15.0,\n      "description": "One of Vietnam\'s most spectacular mountain passes with dramatic cliff views."\n    },\n    {\n      "name": "Vuong Palace",\n      "distance": 2.0,\n      "description": "Historic mansion of the Vuong family, showcasing H\'mong king\'s residence."\n    },\n    {\n      "name": "Lung Cu Flagpole",\n      "distance": 25.0,\n      "description": "Northernmost point of Vietnam marked by a giant flagpole."\n    }\n  ],\n  "transportations": [\n    {\n      "icon": "🛵",\n      "title": "Motorbike",\n      "description": "Most popular way to explore with freedom to stop at scenic viewpoints."\n    },\n    {\n      "icon": "🚐",\n      "title": "Private Van",\n      "description": "Comfortable option for families or those not comfortable with motorbikes."\n    },\n    {\n      "icon": "🚌",\n      "title": "Local Bus",\n      "description": "Budget option with connections between major towns in the geopark."\n    }\n  ],\n  "weather": {\n    "current": {\n      "temperature": 25,\n      "feelsLike": 27,\n      "condition": "Cool and Cloudy",\n      "humidity": "80%",\n      "wind": "18 km/h",\n      "uvIndex": "6"\n    },\n    "forecast": [\n      {\n        "day": "Sunday",\n        "icon": "🌥️",\n        "high": "28°C",\n        "low": "18°C"\n      },\n      {\n        "day": "Monday",\n        "icon": "🌦️",\n        "high": "24°C",\n        "low": "15°C"\n      },\n      {\n        "day": "Tuesday",\n        "icon": "☁️",\n        "high": "26°C",\n        "low": "17°C"\n      },\n      {\n        "day": "Wednesday",\n        "icon": "🌤️",\n        "high": "29°C",\n        "low": "19°C"\n      },\n      {\n        "day": "Thursday",\n        "icon": "🌫️",\n        "high": "23°C",\n        "low": "16°C"\n      }\n    ],\n    "seasons": [\n      {\n        "season": "Dry Season",\n        "description": "October to March with clear skies and cool temperatures ideal for trekking.",\n        "recommendation": "Best time to visit with excellent visibility and comfortable weather for outdoor activities."\n      },\n      {\n        "season": "Rainy Season",\n        "description": "April to September with lush landscapes but possible road difficulties.",\n        "recommendation": "Beautiful green scenery but mountain roads can be challenging during heavy rains."\n      }\n    ]\n  }\n}\n',
